update public.history_content set data = data || '{"page_title":"Uma história de laços\nque atravessam gerações.","page_intro":"De Omaha ao Rio de Janeiro, a mesma vontade de aprender, servir e crescer juntas.","origin_text":"Em 20 de outubro de 1920, Ethel T. Wead Mick fundou as Filhas de Jó em Omaha, Nebraska, nos Estados Unidos. Conhecida carinhosamente como Mãe Mick, ela idealizou uma organização dedicada à formação de jovens mulheres, inspirada no Livro de Jó.\n\nAmizade, respeito e desenvolvimento do caráter estão na origem dessa caminhada. Ao longo das gerações, esses ideais ganharam vida nos Bethels e atravessaram fronteiras.","origin_source":"https://jobsdaughtersinternational.org/our-founder/","brazil_text":"A história brasileira começou no Rio de Janeiro: em 13 de março de 1993, foi instituído o primeiro Bethel do país. Alberto Mansur teve papel central na chegada da organização ao Brasil.\n\nA partir desse primeiro passo, novas comunidades se formaram em outros estados. O Rio também participou dessa expansão: em dezembro de 1998, integrantes do Bethel 1 carioca viajaram a São José do Rio Preto para instalar o primeiro Bethel paulista, conforme o relato preservado pela Assembleia Legislativa de São Paulo.","brazil_source":"https://jobsdaughtersinternational.org/wp-content/uploads/2021/11/Book-of-Ceremonies-Complete-PT-2021.pdf#page=93","brazil_expansion_source":"https://www.al.sp.gov.br/repositorio/ementario/anexos/20140331-173441-ID_SESSAO%3D11269.htm","rio_text":"O Rio guarda o início da nossa trajetória no Brasil. A memória dos seus Bethels reúne histórias de meninas, famílias e voluntários que ajudaram a construir essa irmandade. Conheça alguns desses registros históricos.","bethels_note":"Este é um acervo histórico em construção, não uma relação completa de Bethels em atividade. Informações sobre funcionamento e novas histórias podem ser confirmadas com a equipe.","timeline":[{"date":"20 out. 1920","title":"O sonho de Mãe Mick","text":"A organização nasce em Omaha, Nebraska, sob a liderança de Ethel T. Wead Mick.","source":"https://jobsdaughtersinternational.org/our-founder/"},{"date":"13 mar. 1993","title":"O Brasil começa pelo Rio","text":"É instituído no Rio de Janeiro o primeiro Bethel brasileiro.","source":"https://jobsdaughtersinternational.org/wp-content/uploads/2021/11/Book-of-Ceremonies-Complete-PT-2021.pdf#page=93"},{"date":"15 jun. 1997","title":"Mais uma história carioca","text":"Segundo o relato de Maria Alice Jarcem, nasce em Olaria o Bethel então chamado Obreiras de Irajá, posteriormente Susie Holmes.","source":"https://fdjbrasil.blogspot.com/2012/03/bethel-susie-holmes.html"},{"date":"19 dez. 1998","title":"Laços que chegam a São Paulo","text":"O Bethel 1 do Rio participa da instalação do primeiro Bethel paulista, em São José do Rio Preto.","source":"https://www.al.sp.gov.br/repositorio/ementario/anexos/20140331-173441-ID_SESSAO%3D11269.htm"}],"bethels":[{"name":"Bethel 001 — Mater da América Latina","city":"Rio de Janeiro · RJ","founded":"13 de março de 1993","text":"O primeiro Bethel do Brasil foi instituído no Rio. O registro comemorativo publicado pelo BlogFDJBRASIL identifica o grupo como Mater da América Latina e situa sua fundação no Hotel Glória. Um marco que liga a cidade ao começo da caminhada brasileira.","source":"https://fdjbrasil.blogspot.com/2018/03/25-anos-de-filhas-de-jo-brasil.html","source_label":"Registro dos 25 anos · BlogFDJBRASIL"},{"name":"Bethel Susie Holmes","city":"Rio de Janeiro · RJ","founded":"15 de junho de 1997","text":"Em relato assinado por Maria Alice Jarcem, Past Honorável Rainha, o Bethel nasceu em Olaria com o nome Obreiras de Irajá. A memória publicada em 2012 registra sua mudança de sede em 2001 e a adoção do nome Susie Holmes, em homenagem a uma Filha de Jó.","source":"https://fdjbrasil.blogspot.com/2012/03/bethel-susie-holmes.html","source_label":"Memória de Maria Alice Jarcem · BlogFDJBRASIL"}]}'::jsonb where active and not (data ? 'page_title');
update public.history_content set data=jsonb_set(data,'{image}','"/assets/ethel-mick.gif"'::jsonb) where data->>'image'='/assets/ethel-mick.jpg';
update public.history_content set data=replace(data::text,'https://fdjbrasil.blogspot.com/2012/03/','https://fdjbrasil.blogspot.com/2012/03/bethel-susie-holmes.html')::jsonb where data::text like '%https://fdjbrasil.blogspot.com/2012/03/"%';
update public.hero_content set data=jsonb_set(data,'{primary_url}','"/historia"'::jsonb) where data->>'primary_url'='#historia';
